def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split off pre-release (after '-')
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            prerelease_parsed = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_parsed.append((0, int(part)))  # 0 for numeric
                else:
                    prerelease_parsed.append((1, part))  # 1 for non-numeric
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_parsed = parse_version(version)

        # For sorting:
        # 1. Compare MAJOR.MINOR.PATCH
        # 2. Version with prerelease comes before version without
        # 3. Compare prerelease identifiers

        if prerelease_parsed is None:
            # No pre-release: (major, minor, patch, 1, [])
            return (major, minor, patch, 1, [])
        else:
            # Has pre-release: (major, minor, patch, 0, prerelease_parsed)
            return (major, minor, patch, 0, prerelease_parsed)

    # Sort with stable sort (keeping original order for equal items)
    indexed = list(enumerate(versions))
    indexed.sort(key=sort_key)

    return [v for _, v in indexed]

